import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry the_entry_name(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 O_ptr,
    .param .u64 S_ptr,
    .param .u32 B_param,
    .param .u32 H_param,
    .param .u32 L_param,
    .param .u32 D_param
)
{
    .reg .pred  %p0, %p1, %p2, %p3;
    .reg .u32   %rB, %rH, %rL, %rD;
    .reg .u32   %rb, %rh, %ri, %rj, %rd;
    .reg .u64   %Q, %K, %V, %O, %S;
    .reg .u64   %q_base_b, %o_base_b, %s_base_b;
    .reg .u64   %q_cur, %k_cur, %v_cur, %s_cur, %o_cur;
    .reg .u64   %tmp64a, %tmp64b, %tmp64c, %tmp64d, %tmp64e, %tmp64f, %row_stride_b, %bh_elems64, %idx_bhi64, %idx_elems64, %D64, %L64, %H64, %two_b, %four_b, %row_off_elems64, %row_off_b;
    .reg .f16   %hq, %hk, %hv, %hout16;
    .reg .u16   %q16, %k16, %v16, %o16;
    .reg .f32   %f_acc, %f_q, %f_k, %f_v;
    .reg .f32   %f_m, %f_s, %f_x, %f_new_m;
    .reg .f32   %f_t1, %f_t2, %f_e1, %f_e2, %f_snew, %f_invs, %f_alpha, %f_beta;
    .reg .f32   %f_old, %f_new, %f_scale, %f_Df, %f_tmp, %f_log2e;
    // Load parameters
    ld.param.u64 %Q, [Q_ptr];
    ld.param.u64 %K, [K_ptr];
    ld.param.u64 %V, [V_ptr];
    ld.param.u64 %O, [O_ptr];
    ld.param.u64 %S, [S_ptr];
    ld.param.u32 %rB, [B_param];
    ld.param.u32 %rH, [H_param];
    ld.param.u32 %rL, [L_param];
    ld.param.u32 %rD, [D_param];
    // Convert generic pointers to global
    cvta.to.global.u64 %Q, %Q;
    cvta.to.global.u64 %K, %K;
    cvta.to.global.u64 %V, %V;
    cvta.to.global.u64 %O, %O;
    cvta.to.global.u64 %S, %S;
    // Get block indices (one thread per block)
    mov.u32 %rb, %ctaid.z;
    mov.u32 %rh, %ctaid.y;
    mov.u32 %ri, %ctaid.x;
    // Bounds checks
    setp.ge.u32 %p0, %rb, %rB;
    @%p0 bra DONE;
    setp.ge.u32 %p1, %rh, %rH;
    @%p1 bra DONE;
    setp.ge.u32 %p2, %ri, %rL;
    @%p2 bra DONE;
    // Precompute constants
    cvt.u64.u32 %D64, %rD;
    cvt.u64.u32 %L64, %rL;
    cvt.u64.u32 %H64, %rH;
    // Compute index for (b,h,i)
    // t0 = b * H
    mul.wide.u32 %tmp64a, %rb, %rH;        // u64
    cvt.u64.u32  %tmp64e, %rh;
    add.u64 %tmp64a, %tmp64a, %tmp64e;     // t1 = b*H + h
    mul.lo.u64 %tmp64b, %tmp64a, %L64;     // t2 = (b*H + h) * L
    cvt.u64.u32  %tmp64f, %ri;
    add.u64 %idx_bhi64, %tmp64b, %tmp64f;  // idx_bhi = t2 + i
    // idx_elems = idx_bhi * D
    mul.lo.u64 %idx_elems64, %idx_bhi64, %D64;
    // Byte sizes
    mov.u64 %two_b, 2;
    mov.u64 %four_b, 4;
    // Base byte offsets for Q (half), O (half), Scratch S (float)
    mul.lo.u64 %q_base_b, %idx_elems64, %two_b;    // half = 2 bytes
    mov.u64 %o_base_b, %q_base_b;                  // same shape and dtype half
    mul.lo.u64 %s_base_b, %idx_elems64, %four_b;   // float = 4 bytes
    // Compute base for (b,h,0,0) in K and V: ((b*H + h) * L * D) * 2
    // bh_elems = (b*H + h) * L
    mul.wide.u32 %tmp64c, %rb, %rH;
    cvt.u64.u32 %tmp64e, %rh;
    add.u64 %tmp64c, %tmp64c, %tmp64e;             // b*H + h
    mul.lo.u64 %bh_elems64, %tmp64c, %L64;         // (b*H + h) * L
    // row_stride_bytes = D * 2
    mul.lo.u64 %row_stride_b, %D64, %two_b;
    // base_bytes = bh_elems * D * 2
    mul.lo.u64 %tmp64d, %bh_elems64, %D64;
    mul.lo.u64 %tmp64d, %tmp64d, %two_b;           // tmp64d = base bytes for K/V rows at j=0
    // Compute scaling factor 1/sqrt(D)
    cvt.rn.f32.u32 %f_Df, %rD;
    sqrt.rn.f32 %f_tmp, %f_Df;
    rcp.rn.f32 %f_scale, %f_tmp;
    // log2(e)
    mov.f32 %f_log2e, 1.44269504;
    // Initialize streaming softmax state
    mov.f32 %f_m, -1.0000000e+20;
    mov.f32 %f_s, 0.0;
    // Initialize scratch vector to 0.0
    add.u64 %s_cur, %S, %s_base_b;
    mov.u32 %rd, 0;
    mov.f32 %f_tmp, 0.0;
INIT_LOOP:
    setp.ge.u32 %p3, %rd, %rD;
    @%p3 bra INIT_DONE;
    st.global.f32 [%s_cur], %f_tmp;
    add.u64 %s_cur, %s_cur, %four_b;
    add.u32 %rd, %rd, 1;
    bra INIT_LOOP;
INIT_DONE:
    // j loop over sequence length
    mov.u32 %rj, 0;
J_LOOP:
    setp.ge.u32 %p0, %rj, %rL;
    @%p0 bra AFTER_J;
    // Compute K row base pointer for (b,h,j,0)
    // row_off_elems64 = j * D
    mul.wide.u32 %row_off_elems64, %rj, %rD;   // u64
    // row_off_b = row_off_elems64 * 2
    mul.lo.u64 %row_off_b, %row_off_elems64, %two_b;
    add.u64 %k_cur, %K, %tmp64d;               // base (b,h,0,0)
    add.u64 %k_cur, %k_cur, %row_off_b;        // add j*D*2
    // Compute V row base pointer for (b,h,j,0)
    add.u64 %v_cur, %V, %tmp64d;
    add.u64 %v_cur, %v_cur, %row_off_b;
    // Q current pointer reset to start of (b,h,i,0)
    add.u64 %q_cur, %Q, %q_base_b;
    // Dot product acc = dot(Q[b,h,i,:], K[b,h,j,:])
    mov.f32 %f_acc, 0.0;
    mov.u32 %rd, 0;
DOT_LOOP:
    setp.ge.u32 %p1, %rd, %rD;
    @%p1 bra DOT_DONE;
    ld.global.u16 %q16, [%q_cur];
    ld.global.u16 %k16, [%k_cur];
    mov.b16 %hq, %q16;
    mov.b16 %hk, %k16;
    cvt.f32.f16 %f_q, %hq;
    cvt.f32.f16 %f_k, %hk;
    fma.rn.f32 %f_acc, %f_q, %f_k, %f_acc;
    add.u64 %q_cur, %q_cur, %two_b;
    add.u64 %k_cur, %k_cur, %two_b;
    add.u32 %rd, %rd, 1;
    bra DOT_LOOP;
DOT_DONE:
    // x = acc * scale
    mul.f32 %f_x, %f_acc, %f_scale;
    // new_m = max(m, x)
    max.f32 %f_new_m, %f_m, %f_x;
    // e1 = exp(m - new_m)
    sub.f32 %f_t1, %f_m, %f_new_m;
    mul.f32 %f_t1, %f_t1, %f_log2e;
    ex2.approx.f32 %f_e1, %f_t1;
    // e2 = exp(x - new_m)
    sub.f32 %f_t2, %f_x, %f_new_m;
    mul.f32 %f_t2, %f_t2, %f_log2e;
    ex2.approx.f32 %f_e2, %f_t2;
    // s_new = s * e1 + e2
    mul.f32 %f_tmp, %f_s, %f_e1;
    add.f32 %f_snew, %f_tmp, %f_e2;
    // inv s_new
    rcp.rn.f32 %f_invs, %f_snew;
    // alpha = (s * e1) / s_new
    mul.f32 %f_alpha, %f_tmp, %f_invs;
    // beta = e2 / s_new
    mul.f32 %f_beta, %f_e2, %f_invs;
    // update m and s
    mov.f32 %f_m, %f_new_m;
    mov.f32 %f_s, %f_snew;
    // Update output scratch: O = O * alpha + V * beta
    add.u64 %s_cur, %S, %s_base_b;    // reset scratch pointer
    // v_cur already at start of V row (reset for accumulation loop)
    // Recompute v_cur for start of row
    add.u64 %v_cur, %V, %tmp64d;
    add.u64 %v_cur, %v_cur, %row_off_b;
    mov.u32 %rd, 0;
UPDATE_LOOP:
    setp.ge.u32 %p2, %rd, %rD;
    @%p2 bra UPDATE_DONE;
    ld.global.f32 %f_old, [%s_cur];
    ld.global.u16 %v16, [%v_cur];
    mov.b16 %hv, %v16;
    cvt.f32.f16 %f_v, %hv;
    // f_new = f_old * alpha + f_v * beta
    mul.f32 %f_tmp, %f_old, %f_alpha;
    fma.rn.f32 %f_new, %f_v, %f_beta, %f_tmp;
    st.global.f32 [%s_cur], %f_new;
    add.u64 %s_cur, %s_cur, %four_b;
    add.u64 %v_cur, %v_cur, %two_b;
    add.u32 %rd, %rd, 1;
    bra UPDATE_LOOP;
UPDATE_DONE:
    // Next j
    add.u32 %rj, %rj, 1;
    bra J_LOOP;
AFTER_J:
    // Convert scratch (f32) to output (f16)
    add.u64 %s_cur, %S, %s_base_b;
    add.u64 %o_cur, %O, %o_base_b;
    mov.u32 %rd, 0;
CONVERT_LOOP:
    setp.ge.u32 %p3, %rd, %rD;
    @%p3 bra CONVERT_DONE;
    ld.global.f32 %f_old, [%s_cur];
    cvt.rn.f16.f32 %hout16, %f_old;
    mov.b16 %o16, %hout16;
    st.global.u16 [%o_cur], %o16;
    add.u64 %s_cur, %s_cur, %four_b;
    add.u64 %o_cur, %o_cur, %two_b;
    add.u32 %rd, %rd, 1;
    bra CONVERT_LOOP;
CONVERT_DONE:
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.is_cuda and K.is_cuda and V.is_cuda
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16
        B, H, L, D = Q.shape
        O = torch.empty((B, H, L, D), device=Q.device, dtype=torch.float16)
        # Scratch buffer for f32 accumulation
        S = torch.empty((B, H, L, D), device=Q.device, dtype=torch.float32)

        module = _get_ptx_module()
        module.launch(
            "the_entry_name",
            grid=(L, H, B),
            block=(1, 1, 1),
            arguments=[Q, K, V, O, S, u32(B), u32(H), u32(L), u32(D)],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return O

